<script setup lang="ts">
import { computed, ref } from 'vue'
import AppModal from '../../components/conservation/AppModal.vue'
import { conservationStore, plantFor, speciesForPlant, type SensorDevice, type SensorReading } from '../../data/conservation'
const search=ref(''),status=ref(''),type=ref(''),zone=ref(''),device=ref<SensorDevice|null>(null),reading=ref<SensorReading|null>(null),showReadings=ref(false)
const filtered=computed(()=>conservationStore.devices.filter(d=>`${d.id} ${d.name} ${d.plantId}`.toLowerCase().includes(search.value.toLowerCase())&&(!status.value||d.status===status.value)&&(!type.value||d.type===type.value)&&(!zone.value||d.zone===zone.value)))
const cards=computed(()=>[['Total Devices',conservationStore.devices.length],['Online Devices',conservationStore.devices.filter(d=>d.status==='Online').length],['Offline Devices',conservationStore.devices.filter(d=>d.status==='Offline').length],['Latest Readings',conservationStore.readings.length],['Devices With Alerts',new Set(conservationStore.alerts.filter(a=>a.status!=='Resolved').map(a=>a.sensorId)).size]])
</script>
<template><section class="page-intro"><div><p class="page-kicker">ENVIRONMENTAL NETWORK</p><h2>IoT Monitoring</h2><p>Monitor sensor health and environmental readings near protected plants.</p></div></section><section class="summary-grid"><article v-for="c in cards" :key="String(c[0])" class="summary-card"><p>{{c[0]}}</p><strong>{{c[1]}}</strong><small>Live prototype state</small></article></section><div class="control-bar"><label class="field search-field"><span>Search</span><input v-model="search" placeholder="Device ID, name or Plant ID" /></label><label class="field"><span>Device status</span><select v-model="status"><option value="">All statuses</option><option>Online</option><option>Offline</option><option>Maintenance</option></select></label><label class="field"><span>Device type</span><select v-model="type"><option value="">All types</option><option v-for="t in [...new Set(conservationStore.devices.map(d=>d.type))]" :key="t">{{t}}</option></select></label><label class="field"><span>Zone</span><select v-model="zone"><option value="">All zones</option><option>Zone A</option><option>Zone B</option><option>Zone C</option></select></label></div><section class="panel"><header class="panel-header"><div><h2>Sensor Devices</h2><span class="panel-description">Monitoring-focused access for Conservation Officers.</span></div></header><div class="table-scroll"><table><thead><tr><th>Sensor ID</th><th>Device Name</th><th>Device Type</th><th>Assigned Plant</th><th>Location</th><th>Status</th><th>Installed At</th><th>Last Reading</th><th>Actions</th></tr></thead><tbody><tr v-for="d in filtered" :key="d.id"><td><strong>{{d.id}}</strong></td><td>{{d.name}}</td><td>{{d.type}}</td><td>{{d.plantId}}</td><td>{{d.zone}}</td><td><span class="badge" :class="d.status.toLowerCase()">{{d.status}}</span></td><td>{{d.installedAt}}</td><td>{{d.lastReading}}</td><td><div class="action-group"><button class="action-button" @click="device=d">View</button><button class="action-button" @click="device=d;showReadings=true">View Readings</button><RouterLink class="action-button" :to="{name:'conservation-map',query:{plant:d.plantId}}">Location</RouterLink></div></td></tr></tbody></table></div></section><section class="panel"><header class="panel-header"><div><h2>Recent Sensor Readings</h2></div></header><div class="table-scroll"><table><thead><tr><th>Reading ID</th><th>Sensor ID</th><th>Plant ID</th><th>Temperature</th><th>Humidity</th><th>Soil Moisture</th><th>Rainfall</th><th>Light</th><th>Motion</th><th>GPS</th><th>Recorded At</th><th>Actions</th></tr></thead><tbody><tr v-for="r in conservationStore.readings" :key="r.id"><td><strong>{{r.id}}</strong></td><td>{{r.sensorId}}</td><td>{{r.plantId}}</td><td>{{r.temperature}}</td><td>{{r.humidity}}</td><td>{{r.soilMoisture}}</td><td>{{r.rainfall}}</td><td>{{r.light}}</td><td><span class="badge" :class="r.motion==='Detected'?'high':'approved'">{{r.motion}}</span></td><td>{{r.gps}}</td><td>{{r.recordedAt}}</td><td><div class="action-group"><button class="action-button" @click="reading=r">Details</button><RouterLink class="action-button" :to="{name:'conservation-observations',query:{plant:r.plantId}}">Plant</RouterLink><RouterLink class="action-button" :to="{name:'conservation-map',query:{plant:r.plantId}}">Location</RouterLink></div></td></tr></tbody></table></div></section>
<AppModal v-if="device&&!showReadings" :title="device.name" :subtitle="device.id" @close="device=null"><dl class="detail-list"><div><dt>Assigned Plant</dt><dd>{{device.plantId}} · {{speciesForPlant(device.plantId)?.scientificName}}</dd></div><div><dt>Status</dt><dd>{{device.status}}</dd></div><div><dt>Location</dt><dd>{{device.zone}} · {{plantFor(device.plantId)?.location}}</dd></div><div><dt>Last Reading</dt><dd>{{device.lastReading}}</dd></div></dl></AppModal><AppModal v-if="device&&showReadings" :title="`${device.id} Readings`" wide @close="showReadings=false;device=null"><div class="table-scroll"><table><thead><tr><th>ID</th><th>Temperature</th><th>Humidity</th><th>Soil</th><th>Motion</th><th>Recorded</th></tr></thead><tbody><tr v-for="r in conservationStore.readings.filter(x=>x.sensorId===device?.id)" :key="r.id"><td>{{r.id}}</td><td>{{r.temperature}}</td><td>{{r.humidity}}</td><td>{{r.soilMoisture}}</td><td>{{r.motion}}</td><td>{{r.recordedAt}}</td></tr></tbody></table></div></AppModal><AppModal v-if="reading" :title="`Reading ${reading.id}`" :subtitle="`${reading.sensorId} · ${reading.plantId}`" @close="reading=null"><dl class="detail-list"><div v-for="(value,key) in reading" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></div></dl></AppModal></template>
<style scoped>a.action-button{text-decoration:none}</style>
